import{_ as a,o as i,c as t,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/schueler/tutorials-g89-1-gliederung.png",u="/bilder/schueler/tutorials-g89-2-statistikjahrgaenge.png",d="/bilder/schueler/tutorials-g89-3-versetzungstabelle.png",h="/bilder/schueler/tutorials-g89-4-su-s-waehlen.png",o="/bilder/schueler/tutorials-g89-5-gruppenprozess-su-s.png",g="/bilder/schueler/tutorials-g89-6-gruppenprozess-abschlussdatum.png",w=JSON.parse('{"title":"Ein Gymnasium schrittweise von G8 auf G9 umstellen","description":"","frontmatter":{"title":"Ein Gymnasium schrittweise von G8 auf G9 umstellen","source_pageid":911,"source_revision":5494},"headers":[],"relativePath":"schild3/schueler/umstellung-der-gymnasien-von-g8-auf-g9-tutorial.md","filePath":"schild3/schueler/umstellung-der-gymnasien-von-g8-auf-g9-tutorial.md"}'),c={name:"schild3/schueler/umstellung-der-gymnasien-von-g8-auf-g9-tutorial.md"};function m(p,r,b,f,S,k){return i(),t("div",null,[...r[0]||(r[0]=[s('<h1 id="ein-gymnasium-schrittweise-von-g8-auf-g9-umstellen" tabindex="-1">Ein Gymnasium schrittweise von G8 auf G9 umstellen <a class="header-anchor" href="#ein-gymnasium-schrittweise-von-g8-auf-g9-umstellen" aria-label="Permalink to &quot;Ein Gymnasium schrittweise von G8 auf G9 umstellen&quot;">​</a></h1><p>Passen Sie Gliederungen, Statistikjahrgänge, Klassen und Schülerdaten im Rahmen des Schuljahreswechsels an. Die Umstellung erfolgt jahrgangsweise über mehrere Schuljahre.</p><p>Diese Anleitung führt schrittweise durch die Umstellung eines Gymnasiums von G8 zu G9. Hierbei ist zu beachten, dass für die Umstellung jedes Jahr eine Anpassung vorzunehmen ist, bis alle Jahrgänge in G9 laufen.</p><p>Die Maßnahmen zur Umstellung werden im Rahmen eines Schuljahreswechsels vorgenommen.</p><h2 id="_1-den-programmstand-aktualisieren" tabindex="-1">1. Den Programmstand aktualisieren <a class="header-anchor" href="#_1-den-programmstand-aktualisieren" aria-label="Permalink to &quot;1. Den Programmstand aktualisieren&quot;">​</a></h2><p>Achten Sie darauf, vor der ersten Umstellung auf eine aktuelle Version von SchILD-NRW zu installieren.</p><h2 id="_2-den-schuljahreswechsel-abschließen" tabindex="-1">2. Den Schuljahreswechsel abschließen <a class="header-anchor" href="#_2-den-schuljahreswechsel-abschließen" aria-label="Permalink to &quot;2. Den Schuljahreswechsel abschließen&quot;">​</a></h2><p>Bevor Umstellungen vorgenommen werden, wird die Schule in das neue Schuljahr versetzt und alle Prozesse, die mit Klassen und Jahrgängen in diesem Zuge vorgenommen werden, sind abzuschließen.</p><h2 id="_3-die-gliederung-g9-hinzufugen" tabindex="-1">3. Die Gliederung G9 hinzufügen <a class="header-anchor" href="#_3-die-gliederung-g9-hinzufugen" aria-label="Permalink to &quot;3. Die Gliederung G9 hinzufügen&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-g89-1-gliederung.png"><img src="'+l+'" alt="Hinzufügen der Gliederung &quot;GY9&quot; in Verwaltung ➜ Schule ➜Allgemeine Angaben." loading="lazy"></a></p><p><em>Hinzufügen der Gliederung &quot;GY9&quot; in Verwaltung ➜ Schule ➜Allgemeine Angaben.</em></p><p>Gehen Sie über <em>Verwaltung ➜ Schule ➜ Allgemeine Angaben</em> und fügen Sie die Gliederung GY9 der Schule hinzu, so dass diese für Jahrgänge und bei den Schülern gesetzt werden kann.</p><h2 id="_4-anpassen-der-statistikjahrgange" tabindex="-1">4. Anpassen der Statistikjahrgänge <a class="header-anchor" href="#_4-anpassen-der-statistikjahrgange" aria-label="Permalink to &quot;4. Anpassen der Statistikjahrgänge&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-g89-2-statistikjahrgaenge.png"><img src="'+u+'" alt="Anpassen der Statistikjahrgänge." loading="lazy"></a></p><p><em>Anpassen der Statistikjahrgänge.</em></p><p>Öffnen Sie <em>Kataloge</em> ➜ <strong>Statistik-Jahrgänge</strong>.</p><p>Ändern Sie in der Spalte <strong>Gliederung Klartext</strong> mit Hilfe des Auswahlmenüs die Einträge der Jahrgangsstufen 5 und 6 von &quot;<strong>***</strong>&quot; auf &quot;<strong>GY9</strong>&quot;. Der alte Jahrgang 5, nun nach der Versetzung Jahrgang 6, läuft als GY9 weiter. Die neuen 5er werden als GY9 aufgenommen.</p><p>Korrigieren Sie in der <em>Jahrgangsstufe 5</em> die Spalte <strong>Restabschnitte</strong> auf den Wert <em>18</em> und in der <em>Jahrgangsstufe 6</em> auf den Wert <em>16</em>, also jeweils 2 mehr.</p><p>Sofern sie in SchILD-NRW keinen Halbjahresbetrieb, sondern den Quartalsbetrieb eingerichtet haben, müssen hier die Restabschnitte 36 und 32 eingetragen werden, also jeweils 4 mehr.</p><p>Ändern Sie anschließend auf gleiche Weise in der Spalte &quot;Gliederung Klartext&quot; mit Hilfe des Auswahlmenüs die Einträge der <em>Jahrgangsstufen 7 bis Q2</em> von &quot;<strong>***</strong>&quot; auf &quot;<strong>GY8</strong>&quot;.</p><p>Bestätigen Sie eventuelle Änderungen mit dem Haken ✔.</p>',21),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Der Schritt, dass schrittweise G9 und die Restabschnitte angepasst werden, ist jedes Schuljahr zu wiederholen, bis der erste G9-Jahrgang komplett bis zum Abitur durchgewandert ist."),e("p",null,[n("Fügen Sie bei Bedarf den "),e("em",null,"Jahrgang 10"),n(" als "),e("em",null,"GY9-Jahrgang"),n(" hinzu, in den der erste "),e("em",null,"GY9-Jahrgang 9"),n(" hineinwachsen wird.")])],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Eventuell besteht schon ein Jahrgang 10 in Ihrer Schule, der damals bei der Umstellung auf G8 als "),e("em",null,"unsichtbar"),n(" markiert wurde. Klicken Sie den Haken bei "),e("strong",null,'Nur "sichtbare" Datensätze zeigen'),n(" weg und stellen Sie den alten Jahrgang nun wieder auf "),e("em",null,"sichtbar"),n(". Dann kann der Haken wieder gesetzt werden.")])],-1),s('<h2 id="_5-anpassen-der-klassen-und-versetzungstabelle" tabindex="-1">5. Anpassen der Klassen- und Versetzungstabelle <a class="header-anchor" href="#_5-anpassen-der-klassen-und-versetzungstabelle" aria-label="Permalink to &quot;5. Anpassen der Klassen- und Versetzungstabelle&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-g89-3-versetzungstabelle.png"><img src="'+d+'" alt="Anpassen der Klassen- und Versetzungstabelle." loading="lazy"></a></p><p><em>Anpassen der Klassen- und Versetzungstabelle.</em></p><p>Öffnen Sie <em>Kataloge ➜ Klassen/Versetzungstabelle</em>.</p><p>Wechseln sie in der <em>Aktuell ausgewählten Klasse</em>, hier im Beispiel die 05A, <strong>Schulgliederung</strong> auf <em>&quot;GY9&quot;</em>. Wiederholen Sie dies für alle Klassen des 5. und 6. Jahrgangs.</p><p>Korrigieren Sie für die Klassen 07A bis Q2 deren <strong>Schulgliederung</strong> auf den Eintrag <em>&quot;GY8&quot;</em>.</p>',6),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Dieser Schritt, Klassen auf G9 umzustellen, ist jedes Schuljahr für die Klassen des hochwandernden Jahrgangs zu wiederholen, bis der Jahrgang beim Abitur angekommen ist.")],-1),s('<h2 id="_6-anpassen-der-gliederung-bei-den-schulern" tabindex="-1">6. Anpassen der Gliederung bei den Schülern <a class="header-anchor" href="#_6-anpassen-der-gliederung-bei-den-schulern" aria-label="Permalink to &quot;6. Anpassen der Gliederung bei den Schülern&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-g89-4-su-s-waehlen.png"><img src="'+h+'" alt="Wählen Sie die Schüler der Jahrgänge aus, die umgestellt werden sollen." loading="lazy"></a></p><p><em>Wählen Sie die Schüler der Jahrgänge aus, die umgestellt werden sollen.</em></p><p>Nachdem die Schule auf G9 umgestellt wurde und auch die Klassen angepasst wurden, sind noch die Schüler auf die korrekte Gliederung umzustellen.</p><p>Öffnen Sie <em>Auswahl ➜ Schülerfilter</em> und wählen Sie auf dem Reiter <strong>Individual-Daten I <em>die Jahrgänge 5 und 6 aus, indem Sie bei</em> Schuljahr und Abschnitt <em>auf</em></strong> <em>Akt. Abschnitt&#39;</em> klicken und dann bei <em>Jahrgang</em> in der Liste die Jahrgänge 5 und 6 aktivieren.</p><p>Klicken Sie auf <strong>Testen</strong>, es wird ein Fenster angezeigt, wie viele Personen gefunden wurden.</p><p>Klicken Sie auf <strong>Übernehmen</strong>, um mit der Auswahl weiterarbeiten zu können.</p><p><a href="/bilder/schueler/tutorials-g89-5-gruppenprozess-su-s.png"><img src="'+o+'" alt="Anpassen der Gliederung bei den jeweiligen Schülern." loading="lazy"></a></p><p><em>Anpassen der Gliederung bei den jeweiligen Schülern.</em></p><p>Öffnen Sie nun <em>Gruppenprozesse ➜ Allgemein</em>.</p><p>Klicken Sie auf die Schaltfläche <strong>Individualdaten ändern</strong> und tragen Sie im folgenden Fenster auf dem Reiter <em>&quot;Individual-Daten I&quot;</em> im Bereich <em>&quot;Aktuelle Laufbahndaten&quot;</em> unter <strong>Schulgliederung</strong> den Wert <em>&quot;GY9&quot;</em> ein.</p><p>Klicken Sie auf die Schaltfläche <strong>Ausführen</strong>.</p>',12),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[n("Filtern Sie bei der ersten ersten Umstellung der Gliederung nun auf gleiche Weise die Stufen 7 bis Q2 und ändern Sie die Schulgliederung für diese Personen über die Gruppenprozesse auf "),e("em",null,'"GY8"'),n(".")])],-1),s('<p>Wenn alle Einträge umgestellt und übertragen wurden, ist bei allen Schülerinnen und Schülern der Klassen 5 und 6 auf dem Reiter <em>&quot;Individual-Daten I&quot;</em> im Bereich <em>&quot;Aktuelle Laufbahndaten&quot;</em> die neue Gliederung <em>&quot;GY9&quot;</em> zu sehen. Bei allen Schülern der Klassen 7 bis Q2 steht an dieser Stelle nun der Eintrag <em>&quot;GY8&quot;</em>.</p><p>Auch auf dem Unterreiter <em>&quot;Allgemeine Angaben&quot;</em> des Reiters <em>&quot;Akt. Halbjahr&quot;</em> ist die neue Schulgliederung für das Halbjahr zu erkennen.</p><h2 id="_7-abschlussdatum-neu-berechnen" tabindex="-1">7. Abschlussdatum neu berechnen <a class="header-anchor" href="#_7-abschlussdatum-neu-berechnen" aria-label="Permalink to &quot;7. Abschlussdatum neu berechnen&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-g89-6-gruppenprozess-abschlussdatum.png"><img src="'+g+'" alt="Neuberechnung des Abschlussdatums." loading="lazy"></a></p><p><em>Neuberechnung des Abschlussdatums.</em></p><p>Da mitunter die Restabschnitte bei Jahrgängen angepasst wurden, empfiehlt es sich, das <strong>Abschlussdatum</strong> über den entsprechenden Gruppenprozess neu zu berechnen.</p><h2 id="_8-wiederholung-in-folgenden-schuljahren" tabindex="-1">8. Wiederholung in folgenden Schuljahren <a class="header-anchor" href="#_8-wiederholung-in-folgenden-schuljahren" aria-label="Permalink to &quot;8. Wiederholung in folgenden Schuljahren&quot;">​</a></h2><p>In den zukünftigen Schuljahren müssen Sie nach der Versetzung die Punkte 4, 5 und 6 für die hochwachsenden Jahrgänge sukzessive wiederholen, da diese durch die Versetzung zunächst in die Gliederung <em>&quot;GY8&quot;</em> rutschen.</p><p>Der neue Jahrgang kann vor der Versetzung noch nicht angepasst werden, denn beinhaltet er ja die SuS mit der auslaufenden Gliederung <em>&quot;G8&quot;</em>.</p>',9),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Bei Schülern, die im laufenden Schuljahr eine Klasse zurückgehen und bei Schülern, die eine Nachprüfung bestehen, müssen Sie immer daran denken, die Gliederung auf dem Unterreiter "),e("em",null,'"Allgemeine Angaben"'),n(" des Reiters "),e("em",null,'"Akt. Halbjahr"'),n(" anzupassen.")]),e("p",null,[n("Denken Sie bei diesen SuS auch daran, das neue "),e("em",null,"Abschlussdatum"),n(" zu berechnen.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Umstellung_der_Gymnasien_von_G8_auf_G9_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5494.")],-1)])])}const G=a(c,[["render",m]]);export{w as __pageData,G as default};
